  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The new geothermal power plant, ______ is the largest in the region, will significantly boost the nation''s electricity supply.','[{"key": "A", "text": "that"}, {"key": "B", "text": "which"}, {"key": "C", "text": "it"}, {"key": "D", "text": "what"}]'::jsonb,'B','Kalimat ini membutuhkan non-restrictive relative pronoun untuk memberikan informasi tambahan tentang "The new geothermal power plant". Koma sebelum bagian yang kosong menandakan ini adalah informasi tambahan. "Which" digunakan untuk benda dalam klausa non-restriktif seperti ini.','BI',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'If the company ______ in renewable energy sooner, it would have a stronger market position today.','[{"key": "A", "text": "invested"}, {"key": "B", "text": "would invest"}, {"key": "C", "text": "had invested"}, {"key": "D", "text": "invests"}]'::jsonb,'C','Kalimat ini adalah bentuk third conditional (if + past perfect, would have + past participle) yang membicarakan situasi di masa lalu yang tidak terjadi. Klausa ''if'' harus menggunakan past perfect tense.','BI',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The manager insists that all safety reports ______ submitted before the end of the month.','[{"key": "A", "text": "be"}, {"key": "B", "text": "are"}, {"key": "C", "text": "must"}, {"key": "D", "text": "will be"}]'::jsonb,'A','Kalimat ini menggunakan bentuk subjunctive. Setelah kata kerja seperti "insist that," kata kerja dalam klausa berikutnya harus dalam bentuk dasar (bare infinitive), yaitu "be".','BI',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Neither the engineers nor the project manager ______ available to comment on the project delay.','[{"key": "A", "text": "are"}, {"key": "B", "text": "is"}, {"key": "C", "text": "were"}, {"key": "D", "text": "have been"}]'::jsonb,'B','Ketika menggunakan "neither...nor...", kata kerja harus sesuai dengan subjek yang paling dekat dengannya. Subjek yang paling dekat adalah "the project manager" (tunggal), sehingga kata kerja yang benar adalah "is".','BI',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The presentation was cancelled ______ the speaker''s sudden illness.','[{"key": "A", "text": "because"}, {"key": "B", "text": "since"}, {"key": "C", "text": "due to"}, {"key": "D", "text": "as"}]'::jsonb,'C','"Because", "since", dan "as" adalah konjungsi yang harus diikuti oleh klausa (subjek + kata kerja). "The speaker''s sudden illness" adalah frasa kata benda. "Due to" adalah preposisi yang tepat untuk diikuti oleh frasa kata benda.','BI',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'By the end of next year, PLN ______ the electrification project in over 100 remote villages.','[{"key": "A", "text": "will complete"}, {"key": "B", "text": "completed"}, {"key": "C", "text": "is completing"}, {"key": "D", "text": "will have completed"}]'::jsonb,'D','Frasa "By the end of next year" menandakan suatu aksi yang akan sudah selesai pada suatu titik waktu di masa depan. Future Perfect Tense ("will have" + past participle) adalah tenses yang paling tepat untuk digunakan.','BI',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The company is looking for an employee ______ has experience in high-voltage substation maintenance.','[{"key": "A", "text": "which"}, {"key": "B", "text": "whose"}, {"key": "C", "text": "who"}, {"key": "D", "text": "whom"}]'::jsonb,'C','Kalimat ini membutuhkan relative pronoun untuk merujuk kepada "an employee" (seseorang). "Who" digunakan sebagai subjek dari klausa berikutnya ("has experience...").','BI',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN has an ambitious plan to increase the use of renewable energy.','[{"key": "A", "text": "lazy"}, {"key": "B", "text": "aspiring"}, {"key": "C", "text": "content"}, {"key": "D", "text": "indifferent"}]'::jsonb,'B','"Ambitious" berarti memiliki keinginan kuat untuk sukses. "Aspiring" juga berarti memiliki ambisi atau cita-cita yang tinggi.','BI',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'It is crucial for all employees to follow safety procedures.','[{"key": "A", "text": "vital"}, {"key": "B", "text": "optional"}, {"key": "C", "text": "unimportant"}, {"key": "D", "text": "minor"}]'::jsonb,'A','"Crucial" berarti sangat penting atau menentukan. "Vital" memiliki arti yang sama, yaitu sangat penting untuk keberhasilan atau keberlangsungan sesuatu.','BI',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The power supply was intermittent during the storm.','[{"key": "A", "text": "Sporadic"}, {"key": "B", "text": "continuous"}, {"key": "C", "text": "constant"}, {"key": "D", "text": "permanent"}]'::jsonb,'A','"Intermittent" berarti terjadi secara tidak teratur atau sesekali. "Sporadic" adalah sinonim yang paling tepat yang berarti terjadi pada interval yang tidak teratur.','BI',10);
END $$;

