  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'[Teks Bacaan]:
Indonesia''s state-owned electricity company, PLN, is embarking on an ambitious journey to transition from fossil fuels to renewable energy. This strategic shift, known as the energy transition, is crucial for the country to meet its carbon neutrality targets by 2060. The plan involves phasing out coal-fired power plants and simultaneously ramping up the development of renewable energy sources such as solar, hydro, and geothermal power.

One of the main challenges in this transition is ensuring grid stability. Renewable sources like solar and wind are intermittent, meaning they do not generate power consistently. To address this, PLN is investing in smart grid technology and large-scale energy storage solutions, like batteries and pumped-storage hydropower. Furthermore, the transition requires substantial financial investment, estimated to be in the hundreds of billions of dollars. Securing this funding through international partnerships and green financing mechanisms is a key priority for the government and PLN.

[Pertanyaan]: What is the main topic of the passage?','[{"key": "A", "text": "The history of PLN as a state-owned company."}, {"key": "B", "text": "The challenges of solar power in Indonesia."}, {"key": "C", "text": "PLN''s strategy for shifting to renewable energy."}, {"key": "D", "text": "International funding for Indonesian projects."}]'::jsonb,'C','Paragraf pertama memperkenalkan transisi energi PLN, dan paragraf kedua membahas tantangan serta solusinya. Ini menunjukkan fokus utama pada strategi transisi energi.','BI',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'[Teks Bacaan]:
