  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The project ______ on schedule if the main equipment had not been delayed in shipment.','[{"key": "A", "text": "would finish"}, {"key": "B", "text": "will finish"}, {"key": "C", "text": "would have finished"}, {"key": "D", "text": "finished"}]'::jsonb,'C','Kalimat ini adalah bentuk third conditional (if + past perfect, ...would have + past participle), yang digunakan untuk membicarakan situasi hipotetis di masa lalu. Karena kondisi di masa lalu tidak terpenuhi (peralatan terlambat), hasilnya juga tidak terjadi.','BI',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'One of the most significant challenges ______ the unpredictable weather patterns affecting wind turbine performance.','[{"key": "A", "text": "is"}, {"key": "B", "text": "are"}, {"key": "C", "text": "being"}, {"key": "D", "text": "to be"}]'::jsonb,'A','Subjek dari kalimat ini adalah "One of the most significant challenges". Meskipun ada kata "challenges" (jamak), subjek utamanya adalah "One" (satu), yang bersifat tunggal. Oleh karena itu, kata kerja yang benar adalah "is".','BI',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The new system was designed ______ data processing, reporting, and network security.','[{"key": "A", "text": "to improve"}, {"key": "B", "text": "for improving"}, {"key": "C", "text": "improving"}, {"key": "D", "text": "improvement"}]'::jsonb,'A','Setelah frasa "was designed", tujuan atau fungsi dari desain tersebut diungkapkan menggunakan to-infinitive ("to improve").','BI',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'______ the high initial cost, solar panel installation is a wise long-term investment for many households.','[{"key": "A", "text": "Although"}, {"key": "B", "text": "In spite"}, {"key": "C", "text": "Despite"}, {"key": "D", "text": "Because"}]'::jsonb,'C','Kata "Despite" adalah preposisi yang diikuti oleh kata benda atau frasa kata benda ("the high initial cost"). "Although" adalah konjungsi yang harus diikuti oleh klausa (subjek + kata kerja).','BI',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The maintenance team had the damaged transformer ______ by a certified technician.','[{"key": "A", "text": "repair"}, {"key": "B", "text": "repaired"}, {"key": "C", "text": "repairing"}, {"key": "D", "text": "to repair"}]'::jsonb,'B','Kalimat ini menggunakan struktur causative "have something done" (had the damaged transformer repaired), yang berarti menyuruh orang lain untuk melakukan pekerjaan tersebut. Strukturnya adalah have + object + past participle.','BI',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'This is the engineer ______ innovative design won the company an award for efficiency.','[{"key": "A", "text": "who"}, {"key": "B", "text": "which"}, {"key": "C", "text": "whom"}, {"key": "D", "text": "whose"}]'::jsonb,'D','Kata "whose" adalah possessive relative pronoun yang digunakan untuk menunjukkan kepemilikan. Dalam kalimat ini, "desain inovatif" adalah milik "insinyur" (the engineer''s innovative design).','BI',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'All electrical installations in this facility must ______ with international safety standards.','[{"key": "A", "text": "comply"}, {"key": "B", "text": "complies"}, {"key": "C", "text": "complying"}, {"key": "D", "text": "complied"}]'::jsonb,'A','Setelah modal verb seperti "must", kata kerja yang mengikutinya harus dalam bentuk dasar (bare infinitive), yaitu "comply".','BI',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The company plans to implement a new energy-saving policy next month.','[{"key": "A", "text": "cancel"}, {"key": "B", "text": "execute"}, {"key": "C", "text": "discuss"}, {"key": "D", "text": "ignore"}]'::jsonb,'B','"To implement" berarti memulai atau melaksanakan sebuah rencana. "To execute" memiliki arti yang sama, yaitu menjalankan atau melaksanakan.','BI',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Regular maintenance is performed to ensure the reliability of the power grid.','[{"key": "A", "text": "question"}, {"key": "B", "text": "doubt"}, {"key": "C", "text": "guarantee"}, {"key": "D", "text": "weaken"}]'::jsonb,'C','"To ensure" berarti memastikan sesuatu akan terjadi. "To guarantee" adalah sinonim yang paling dekat, yang juga berarti menjamin.','BI',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The control room can monitor multiple substations simultaneously.','[{"key": "A", "text": "separately"}, {"key": "B", "text": "consecutively"}, {"key": "C", "text": "concurrently"}, {"key": "D", "text": "previously"}]'::jsonb,'C','"Simultaneously" berarti terjadi pada waktu yang bersamaan. "Concurrently" adalah sinonim yang tepat untuk makna ini.','BI',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Training programs are designed to enhance the skills of our employees.','[{"key": "A", "text": "reduce"}, {"key": "B", "text": "maintain"}, {"key": "C", "text": "improve"}, {"key": "D", "text": "conceal"}]'::jsonb,'C','"To enhance" berarti meningkatkan kualitas, nilai, atau tingkat sesuatu. "To improve" adalah sinonim yang paling umum dan tepat.','BI',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'A lack of funding has been a major barrier to the project''s completion.','[{"key": "A", "text": "support"}, {"key": "B", "text": "assistance"}, {"key": "C", "text": "opening"}, {"key": "D", "text": "obstacle"}]'::jsonb,'D','"Barrier" adalah sesuatu yang menghalangi kemajuan. "Obstacle" memiliki arti yang sama, yaitu rintangan atau halangan.','BI',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'[Teks Bacaan]:
The concept of a "smart grid" represents a significant evolution from the traditional electrical grid. While the conventional grid is a one-way system where power flows from a central plant to consumers, a smart grid allows for a two-way flow of electricity and information. This is made possible by integrating digital technology, such as sensors, automated controls, and advanced data analytics, across the entire grid. This integration enables electricity companies to respond to changes in demand more quickly and efficiently.

For consumers, a smart grid offers numerous benefits. It allows them to monitor their energy consumption in real-time, helping them to make more informed decisions about their usage and potentially lower their electricity bills. For the grid operator, the technology helps in detecting and isolating outages, thereby reducing downtime and improving the reliability of the power supply. The smart grid is also essential for integrating variable renewable energy sources, like wind and solar, more effectively into the national power system.

[Pertanyaan]: What is the primary difference between a traditional grid and a smart grid?','[{"key": "A", "text": "A traditional grid uses more renewable energy."}, {"key": "B", "text": "A smart grid only allows a one-way flow of electricity."}, {"key": "C", "text": "A smart grid enables a two-way flow of electricity and information."}, {"key": "D", "text": "A traditional grid is more technologically advanced."}]'::jsonb,'C','Teks dengan jelas menyatakan bahwa pergeseran dari aliran satu arah (tradisional) ke aliran dua arah (smart grid) adalah perbedaan utamanya.','BI',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'[Teks Bacaan]:
