  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'If the lead engineer ______ present at the meeting, he would explain the technical details.','[{"key": "A", "text": "is"}, {"key": "B", "text": "was"}, {"key": "C", "text": "were"}, {"key": "D", "text": "had been"}]'::jsonb,'C','Kalimat ini adalah bentuk second conditional (if + simple past, ...would + base verb), yang digunakan untuk situasi hipotetis di masa sekarang. Dalam bentuk ini, untuk subjek ''he/she/it'', secara formal digunakan ''were'' bukan ''was''.','BI',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The responsibilities of the new role include managing projects, ______ reports, and coordinating with other departments.','[{"key": "A", "text": "to write"}, {"key": "B", "text": "writing"}, {"key": "C", "text": "written"}, {"key": "D", "text": "write"}]'::jsonb,'B','Kalimat ini menggunakan struktur paralel. "Managing projects", "writing reports", dan "coordinating" harus dalam bentuk yang sama. Karena "managing" dan "coordinating" adalah gerunds, maka kata yang tepat adalah "writing".','BI',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The safety committee recommended that every employee ______ a refresher course on emergency procedures.','[{"key": "A", "text": "attends"}, {"key": "B", "text": "to attend"}, {"key": "C", "text": "attend"}, {"key": "D", "text": "attending"}]'::jsonb,'C','Ini adalah contoh lain dari subjunctive mood. Setelah kata kerja seperti "recommended that", kata kerja berikutnya harus dalam bentuk dasar (bare infinitive), yaitu "attend".','BI',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The new power station is not only more efficient ______ also more environmentally friendly.','[{"key": "A", "text": "and"}, {"key": "B", "text": "but"}, {"key": "C", "text": "so"}, {"key": "D", "text": "with"}]'::jsonb,'B','Struktur "not only... but also..." adalah pasangan konjungsi yang umum digunakan. Kata "also" terkadang dihilangkan, sehingga menjadi "not only... but...".','BI',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'All project proposals must be submitted ______ 5 PM on Friday.','[{"key": "A", "text": "in"}, {"key": "B", "text": "at"}, {"key": "C", "text": "by"}, {"key": "D", "text": "on"}]'::jsonb,'C','Preposisi "by" digunakan untuk menunjukkan batas waktu atau tenggat waktu (deadline). Artinya, proposal harus diserahkan sebelum atau pada pukul 5 sore hari Jumat.','BI',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'A number of technicians ______ been dispatched to resolve the power outage.','[{"key": "A", "text": "has"}, {"key": "B", "text": "have"}, {"key": "C", "text": "is"}, {"key": "D", "text": "was"}]'::jsonb,'B','Frasa "A number of..." selalu dianggap jamak dan diikuti oleh kata kerja jamak. Sebaliknya, "The number of..." dianggap tunggal.','BI',6);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The manager, ______ the team respects greatly, will be retiring next month.','[{"key": "A", "text": "who"}, {"key": "B", "text": "whom"}, {"key": "C", "text": "whose"}, {"key": "D", "text": "which"}]'::jsonb,'B','Kata ganti "whom" digunakan sebagai objek dari kata kerja dalam klausa relatif. Dalam klausa "the team respects greatly", "the team" adalah subjek dan "whom" (merujuk pada manajer) adalah objek dari kata kerja "respects".','BI',7);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'It is  essential to wear protective gear when working near high-voltage equipment.','[{"key": "A", "text": "optional"}, {"key": "B", "text": "unnecessary"}, {"key": "C", "text": "advisable"}, {"key": "D", "text": "vital"}]'::jsonb,'D','"Essential" berarti mutlak diperlukan atau sangat penting. "Vital" memiliki arti yang sama persis.','BI',8);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The company decided to stick with the conventional method of data collection.','[{"key": "A", "text": "traditional"}, {"key": "B", "text": "modern"}, {"key": "C", "text": "innovative"}, {"key": "D", "text": "complicated"}]'::jsonb,'A','"Conventional" berarti berdasarkan pada apa yang secara umum dilakukan atau diyakini. "Traditional" adalah sinonim yang paling tepat.','BI',9);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'New regulations were introduced to mitigate the environmental impact of the factory.','[{"key": "A", "text": "increase"}, {"key": "B", "text": "understand"}, {"key": "C", "text": "reduce"}, {"key": "D", "text": "ignore"}]'::jsonb,'C','"To mitigate" berarti membuat sesuatu yang buruk menjadi tidak terlalu parah atau serius. "To reduce" (mengurangi) adalah sinonim yang paling sesuai.','BI',10);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'We did not anticipate such a rapid increase in electricity demand.','[{"key": "A", "text": "forget"}, {"key": "B", "text": "expect"}, {"key": "C", "text": "cause"}, {"key": "D", "text": "prevent"}]'::jsonb,'B','"To anticipate" berarti menganggap sesuatu mungkin atau mungkin akan terjadi di masa depan. "To expect" (mengharapkan) memiliki arti yang sangat mirip.','BI',11);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'The proposed solution was not considered feasible due to budget limitations.','[{"key": "A", "text": "impossible"}, {"key": "B", "text": "expensive"}, {"key": "C", "text": "practicable"}, {"key": "D", "text": "original"}]'::jsonb,'C','"Feasible" berarti mungkin untuk dilakukan dengan mudah atau nyaman. "Practicable" adalah sinonim yang kuat, yang berarti dapat dilakukan dalam praktik; bisa dijalankan.','BI',12);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'[Teks Bacaan]:
As the energy sector becomes increasingly digitized, cybersecurity has emerged as a paramount concern. Power grids, which are now interconnected with smart technologies, are more vulnerable to cyber threats than ever before. A successful cyberattack on a nation''s power grid could lead to widespread blackouts, disrupt essential services, and compromise national security. Potential threats range from malware designed to disrupt operations to ransomware attacks that hold critical data hostage.

To counter these risks, energy companies are investing heavily in advanced cybersecurity measures. These include developing robust defense systems, conducting regular security audits, and training employees to recognize and respond to phishing attempts and other social engineering tactics. Collaboration between government agencies and private sector companies is also crucial to share threat intelligence and coordinate a unified defense against sophisticated cyber adversaries.

[Pertanyaan]: What is the main idea of the passage?','[{"key": "A", "text": "The benefits of a digitized energy sector."}, {"key": "B", "text": "The rising importance of cybersecurity in the energy industry."}, {"key": "C", "text": "The different types of malware affecting power grids."}, {"key": "D", "text": "The role of employees in preventing cyberattacks."}]'::jsonb,'B','Teks ini secara keseluruhan membahas bagaimana digitalisasi membuat sektor energi rentan terhadap serangan siber dan langkah-langkah untuk melawannya.','BI',13);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'[Teks Bacaan]:
